#include <stdio.h>

struct Tool {
    int id;
    int count;
};

static const struct Tool *find(const struct Tool tools[], size_t count, int id)
{
    for (size_t i = 0; i < count; ++i) {
        if (tools[i].id == id) {
            return &tools[i];
        }
    }
    return NULL;
}

static void print_tool(const struct Tool *tool)
{
    if (tool == NULL) {
        puts("missing");
        return;
    }
    printf("%d %d\n", tool->id, tool->count);
}

int main(void)
{
    const struct Tool tools[] = {{17, 2}, {23, 5}, {42, 1}};
    const size_t count = sizeof tools / sizeof tools[0];
    print_tool(find(tools, count, 23));
    print_tool(find(tools, count, 30));
    return 0;
}

