#include <ctype.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>

static int read_values(int values[], const int minimum[], const int maximum[], size_t count)
{
    char line[64];
    size_t length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == sizeof line - 1) {
            return 0;
        }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) {
        return 0;
    }
    line[length] = '\0';

    char *cursor = line;
    for (size_t i = 0; i < count; ++i) {
        char *end;
        errno = 0;
        long value = strtol(cursor, &end, 10);
        if (end == cursor || errno == ERANGE || value < minimum[i] || value > maximum[i]) {
            return 0;
        }
        if (i + 1 < count && !isspace((unsigned char)*end)) {
            return 0;
        }
        values[i] = (int)value;
        cursor = end;
    }
    while (isspace((unsigned char)*cursor)) {
        ++cursor;
    }
    return *cursor == '\0';
}

struct Delivery {
    int id;
    int quantity;
};

static const struct Delivery *find(const struct Delivery deliveries[], size_t count, int id)
{
    for (size_t i = 0; i < count; ++i) {
        /* TODO: compare the lookup key to the identifier. */
        if (deliveries[i].quantity == id) {
            return &deliveries[i];
        }
    }
    return NULL;
}

int main(void)
{
    int value[1];
    const int minimum[] = {1};
    const int maximum[] = {9999};
    if (!read_values(value, minimum, maximum, 1)) {
        puts("invalid");
        return 0;
    }

    const struct Delivery deliveries[] = {{12, 8}, {31, 3}, {54, 0}, {77, 26}};
    const size_t count = sizeof deliveries / sizeof deliveries[0];
    const struct Delivery *result = find(deliveries, count, value[0]);
    if (result != NULL) {
        printf("%d %d\n", result->id, result->quantity);
    } else {
        puts("missing");
    }
    return 0;
}

